var EARTH_R = 6371.0088;
function toRad(d){ return d*Math.PI/180; }
function toDeg(r){ return r*180/Math.PI; }
function parseLatLng(s){
  var parts=String(s||'').trim().split(/[,\s]+/).filter(function(x){return x.length;});
  if(parts.length!==2) return { value:null, error:'需要「纬度, 经度」两个数' };
  var lat=Number(parts[0]), lng=Number(parts[1]);
  if(!isFinite(lat)||!isFinite(lng)) return { value:null, error:'非法数字' };
  if(lat<-90||lat>90) return { value:null, error:'纬度须在 [-90, 90]' };
  if(lng<-180||lng>180) return { value:null, error:'经度须在 [-180, 180]' };
  return { value:{lat:lat,lng:lng}, error:null };
}
function haversine(a, b){
  var dLat=toRad(b.lat-a.lat), dLng=toRad(b.lng-a.lng);
  var s=Math.sin(dLat/2)*Math.sin(dLat/2) +
        Math.cos(toRad(a.lat))*Math.cos(toRad(b.lat))*Math.sin(dLng/2)*Math.sin(dLng/2);
  return 2*EARTH_R*Math.asin(Math.min(1, Math.sqrt(s)));
}
function bearing(a, b){
  var la=toRad(a.lat), lb=toRad(b.lat), dl=toRad(b.lng-a.lng);
  var y=Math.sin(dl)*Math.cos(lb);
  var x=Math.cos(la)*Math.sin(lb)-Math.sin(la)*Math.cos(lb)*Math.cos(dl);
  return (toDeg(Math.atan2(y,x))+360)%360;
}
function destination(a, bearingDeg, distKm){
  var la=toRad(a.lat), lo=toRad(a.lng), br=toRad(bearingDeg), dr=distKm/EARTH_R;
  var lat2=Math.asin(Math.sin(la)*Math.cos(dr)+Math.cos(la)*Math.sin(dr)*Math.cos(br));
  var lng2=lo+Math.atan2(Math.sin(br)*Math.sin(dr)*Math.cos(la), Math.cos(dr)-Math.sin(la)*Math.sin(lat2));
  var lngDeg=((toDeg(lng2)+540)%360)-180;
  return { lat:toDeg(lat2), lng:lngDeg };
}
function boundingBox(center, radiusKm){
  var dLat=toDeg(radiusKm/EARTH_R);
  var dLng=toDeg(radiusKm/(EARTH_R*Math.cos(toRad(center.lat))));
  return { minLat:center.lat-dLat, maxLat:center.lat+dLat,
           minLng:center.lng-dLng, maxLng:center.lng+dLng };
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { parseLatLng:parseLatLng, haversine:haversine, bearing:bearing,
    destination:destination, boundingBox:boundingBox, EARTH_R:EARTH_R };
}
if (typeof window !== 'undefined') {
  window.GeoForgePure = { parseLatLng:parseLatLng, haversine:haversine, bearing:bearing,
    destination:destination, boundingBox:boundingBox };
}
